def _read_image_for_embed(path: Path, max_px: int):
    """
    Return a PIL Image at or below max_px on the long edge.
    For pyramidal TIFFs, reads the smallest pyramid level that still covers
    max_px — avoiding decoding the full-resolution file entirely.
    Falls back to plain PIL for non-pyramidal or non-TIFF files.
    """
    import contextlib
    import io
    import os
    from PIL import Image as _PILImage
    _PILImage.MAX_IMAGE_PIXELS = None

    is_tiff = path.suffix.lower() in (".tif", ".tiff")
    if is_tiff:
        try:
            import tifffile

            # Suppress tifffile's internal stderr chatter (e.g. discontiguous storage warnings)
            with open(os.devnull, "w") as devnull, contextlib.redirect_stderr(devnull):
                tf = tifffile.TiffFile(str(path))

            # --- Strategy 1: pyramid levels via series ---
            try:
                series = tf.series[0] if tf.series else None
            except Exception:
                series = None

            if series and len(series.levels) > 1:
                best = None
                for level in reversed(series.levels):
                    shape = level.shape
                    h = shape[-3] if len(shape) >= 3 else shape[0]
                    w = shape[-2] if len(shape) >= 3 else shape[1]
                    if max(h, w) >= max_px:
                        best = level
                    else:
                        break
                if best is None:
                    best = series.levels[-1]
                shape = best.shape
                h = shape[-3] if len(shape) >= 3 else shape[0]
                w = shape[-2] if len(shape) >= 3 else shape[1]
                log_detail(f"Using TIFF pyramid level {w}x{h}px from {path.name}.", level=2)
                arr = best.asarray()
                while arr.ndim > 3:
                    arr = arr[0]
                img = _PILImage.fromarray(arr).convert("RGB")
                tf.close()
                if max(img.size) > max_px:
                    img.thumbnail((max_px, max_px), _PILImage.LANCZOS)
                return img

            # --- Strategy 2: SUBFILETYPE reduced-image pages (thumbnail pages) ---
            reduced_pages = [
                p for p in tf.pages
                if getattr(p, "subfiletype", 0) & 0x1  # REDUCEDIMAGE flag
            ]
            if reduced_pages:
                # Pick smallest reduced page that still covers max_px
                best_page = None
                for p in sorted(reduced_pages, key=lambda p: max(p.shape[:2])):
                    if max(p.shape[:2]) >= max_px:
                        best_page = p
                        break
                if best_page is None:
                    best_page = reduced_pages[-1]
                arr = best_page.asarray()
                img = _PILImage.fromarray(arr).convert("RGB")
                tf.close()
                log_detail(f"Using TIFF reduced-image page {img.size[0]}x{img.size[1]}px from {path.name}.", level=2)
                if max(img.size) > max_px:
                    img.thumbnail((max_px, max_px), _PILImage.LANCZOS)
                return img

            tf.close()

        except ImportError:
            log_warning(f"tifffile not installed; falling back to PIL for {path.name}. Install with: pip install tifffile", level=2)
        except Exception as e:
            log_warning(f"tifffile fallback for {path.name}: {e}", level=2)

    # Plain PIL fallback
    img = _PILImage.open(path).convert("RGB")
    if max(img.size) > max_px:
        img.thumbnail((max_px, max_px), _PILImage.LANCZOS)
    return img


def _normalize_section_image_layers(value) -> List[tuple]:
    """Normalize a section_images value into an ordered list of (name, path).

    Accepts, per section:
      - a single path:            "img.tif"
      - a name->path mapping:     {"DAPI": "dapi.png", "H&E": "he.png"}
      - a list of paths:          ["dapi.png", "he.png"]
      - a list of {name, path}:   [{"name": "DAPI", "path": "dapi.png"}, ...]
      - a list of (name, path):   [("DAPI", "dapi.png"), ...]
    """
    layers: List[tuple] = []
    if value is None:
        return layers
    if isinstance(value, (str, Path)):
        layers.append((Path(value).stem, str(value)))
    elif isinstance(value, dict):
        for name, path in value.items():
            if path:
                layers.append((str(name), str(path)))
    elif isinstance(value, (list, tuple)):
        for item in value:
            if isinstance(item, (str, Path)):
                layers.append((Path(item).stem, str(item)))
            elif isinstance(item, dict):
                path = item.get("path") or item.get("url")
                name = item.get("name") or (Path(path).stem if path else "Image")
                if path:
                    layers.append((str(name), str(path)))
            elif isinstance(item, (list, tuple)) and len(item) == 2:
                layers.append((str(item[0]), str(item[1])))
    return layers


def _embed_section_images(data: dict, section_images: Dict[str, object], max_px: int = 4096) -> None:
    """Read image files, downsample if needed, and embed as base64 data URLs.

    Each section may carry one or more named overlay layers (e.g. DAPI + H&E),
    embedded into ``section["he_images"]`` as ``[{"name", "url"}, ...]``. The
    first layer is also mirrored to the legacy ``section["he_image"]`` field.
    """
    import io
    try:
        from PIL import Image as _PILImage  # noqa: F401
        _has_pil = True
    except ImportError:
        _has_pil = False

    section_by_id = {s["id"]: s for s in data.get("sections", [])}
    for section_id, value in section_images.items():
        if section_id not in section_by_id:
            log_warning(f"section_images key '{section_id}' not found in sections; skipping.", level=1)
            continue
        spec = _normalize_section_image_layers(value)
        if not spec:
            continue
        if not _has_pil:
            log_warning("Pillow not installed; cannot embed section images. Install Pillow.", level=1)
            continue
        embedded = []
        for name, image_path in spec:
            path = Path(image_path)
            if not path.exists():
                log_warning(f"section image not found: {image_path}; skipping.", level=1)
                continue
            img = _read_image_for_embed(path, max_px)
            buf = io.BytesIO()
            img.save(buf, format="JPEG", quality=85)
            raw = buf.getvalue()
            url = f"data:image/jpeg;base64,{base64.b64encode(raw).decode()}"
            embedded.append({"name": name, "url": url})
            log_detail(
                f"Embedded {path.name} as '{name}' "
                f"({img.size[0]}x{img.size[1]}px, {len(raw) // 1024}KB) for section '{section_id}'.",
                level=1,
            )
        if embedded:
            section_by_id[section_id]["he_images"] = embedded
            section_by_id[section_id]["he_image"] = embedded[0]["url"]


GENE_SIDECAR_SHARD_SIZE = 256
KAROSPACE_PACKAGE_MANIFEST = "karospace-package.json"
KAROSPACE_PACKAGE_LOADER_FILENAME = "karospace-package-loader.html"
GENE_SIDECAR_FORMAT_BINARY = "binary"
GENE_SIDECAR_BINARY_MAGIC = b"KSB1"
GENE_SIDECAR_BINARY_VERSION = 1
# Keep each JSON payload comfortably below browser string/parser limits.  Large
# viewers split section fields across scripts and reassemble them at startup.
EMBEDDED_VIEWER_DATA_SINGLE_SCRIPT_MAX_CHARS = 16 * 1024 * 1024


def _load_logo_base64() -> Optional[str]:
    """Load logo from assets as base64 string."""
    logo_path = Path(__file__).parent.parent / "assets" / "logo.png"
    if logo_path.exists():
        with open(logo_path, "rb") as f:
            return base64.b64encode(f.read()).decode("utf-8")
    return None


def _chunked(values: List[str], size: int) -> List[List[str]]:
    if size < 1:
        raise ValueError("chunk size must be >= 1")
    return [values[i:i + size] for i in range(0, len(values), size)]


def _isoformat_utc_now() -> str:
    return datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")


def _get_karospace_version() -> str:
    try:
        from . import __version__

        return str(__version__)
    except Exception:
        return "unknown"


def _guess_package_media_type(path: Union[str, Path]) -> str:
    suffix = Path(path).suffix.lower()
    if suffix == ".html":
        return "text/html"
    if suffix == ".json":
        return "application/json"
    if suffix == ".bin":
        return "application/octet-stream"
    return "application/octet-stream"


def _u32_bytes(values: List[int]) -> bytes:
    if not values:
        return b""
    arr = np.asarray(values, dtype="<u4")
    return np.ascontiguousarray(arr).tobytes(order="C")


def _decode_sidecar_packed_bytes(value, *, dtype: str) -> bytes:
    if value is None:
        return b""
    if isinstance(value, str):
        return base64.b64decode(value.encode("ascii"))
    if isinstance(value, (bytes, bytearray, memoryview)):
        return bytes(value)
    arr = np.asarray(value, dtype=dtype)
    return np.ascontiguousarray(arr).tobytes(order="C")


def _binary_payload_kind_from_sections(section_entries: Mapping[str, dict]) -> int:
    kinds = set()
    for section_entry in section_entries.values():
        if not section_entry:
            continue
        if "sparse" in section_entry:
            kinds.add("sparse")
        else:
            kinds.add("dense")
    if kinds == {"dense"}:
        return 1
    if kinds == {"sparse"}:
        return 2
    return 0


def _build_binary_gene_payload(
    *,
    gene_entry: Mapping[str, object],
    section_order: List[str],
    section_cell_counts: Mapping[str, int],
) -> Tuple[int, bytes]:
    section_entries = gene_entry.get("sections") or {}
    payload_kind = _binary_payload_kind_from_sections(section_entries)
    chunks: List[bytes] = [struct.pack("<I", len(section_order))]

    for section_index, section_id in enumerate(section_order):
        section_entry = section_entries.get(section_id) or {}
        cell_count = int(section_cell_counts.get(section_id, 0))
        section_encoding = 0
        nnz = 0
        nan_values: List[int] = []
        section_data = b""

        if "sparse" in section_entry:
            sparse = section_entry.get("sparse") or {}
            index_bytes = _decode_sidecar_packed_bytes(sparse.get("ib64"), dtype="<u4")
            if "vq8b64" in sparse:
                value_bytes = _decode_sidecar_packed_bytes(sparse.get("vq8b64"), dtype="u1")
                section_encoding = 2
            elif "vq16b64" in sparse:
                value_bytes = _decode_sidecar_packed_bytes(sparse.get("vq16b64"), dtype="<u2")
                section_encoding = 4
            else:
                raise ValueError("binary sidecars require quantized sparse sidecar values")
            nnz = len(index_bytes) // 4
            nan_values = [int(v) for v in (sparse.get("nan") or [])]
            section_data = index_bytes + value_bytes
        elif section_entry:
            if "dq8b64" in section_entry:
                value_bytes = _decode_sidecar_packed_bytes(section_entry.get("dq8b64"), dtype="u1")
                section_encoding = 1
            elif "dq16b64" in section_entry:
                value_bytes = _decode_sidecar_packed_bytes(section_entry.get("dq16b64"), dtype="<u2")
                section_encoding = 3
            else:
                raise ValueError("binary sidecars require quantized dense sidecar values")
            nan_values = [int(v) for v in (section_entry.get("nan") or [])]
            section_data = value_bytes

        chunks.append(
            struct.pack(
                "<HBBIII",
                int(section_index),
                int(section_encoding),
                0,
                int(cell_count),
                int(nnz),
                int(len(nan_values)),
            )
        )
        chunks.append(section_data)
        chunks.append(_u32_bytes(nan_values))

    return payload_kind, b"".join(chunks)


def _write_binary_gene_shard(
    *,
    shard_path: Path,
    shard_genes: List[str],
    shard_data: Mapping[str, object],
    section_order: List[str],
    section_cell_counts: Mapping[str, int],
) -> None:
    genes_payload = shard_data.get("genes") or {}
    payload_blobs: List[Tuple[bytes, int, bytes]] = []
    index_size = 0

    for gene in shard_genes:
        gene_name_bytes = str(gene).encode("utf-8")
        payload_kind, payload_bytes = _build_binary_gene_payload(
            gene_entry=genes_payload.get(gene) or {},
            section_order=section_order,
            section_cell_counts=section_cell_counts,
        )
        payload_blobs.append((gene_name_bytes, payload_kind, payload_bytes))
        index_size += 2 + len(gene_name_bytes) + 1 + 1 + 8 + 8

    header = struct.pack(
        "<4sHHII",
        GENE_SIDECAR_BINARY_MAGIC,
        GENE_SIDECAR_BINARY_VERSION,
        0,
        len(payload_blobs),
        0,
    )
    payload_offset = len(header) + index_size
    out = bytearray()
    out.extend(header)

    current_offset = payload_offset
    for gene_name_bytes, payload_kind, payload_bytes in payload_blobs:
        out.extend(struct.pack("<H", len(gene_name_bytes)))
        out.extend(gene_name_bytes)
        out.extend(struct.pack("<BBQQ", payload_kind, 0, current_offset, len(payload_bytes)))
        current_offset += len(payload_bytes)

    for _, _, payload_bytes in payload_blobs:
        out.extend(payload_bytes)

    shard_path.parent.mkdir(parents=True, exist_ok=True)
    with open(shard_path, "wb") as handle:
        handle.write(out)


def _build_karospace_package_manifest(
    *,
    source_root: Path,
    entry_html: str,
    gene_manifest_path: str,
    gene_shard_dir: str,
    title: str,
    n_sections: int,
    total_cells: int,
) -> dict:
    files = {}
    for file_path in sorted(p for p in source_root.rglob("*") if p.is_file()):
        rel_path = file_path.relative_to(source_root).as_posix()
        files[rel_path] = {
            "media_type": _guess_package_media_type(rel_path),
            "size_bytes": int(file_path.stat().st_size),
        }

    return {
        "format": "karospace-package-v1",
        "package_version": 1,
        "entry_html": entry_html,
        "created_at": _isoformat_utc_now(),
        "producer": {
            "name": "karospace",
            "version": _get_karospace_version(),
        },
        "title": title,
        "n_sections": int(n_sections),
        "total_cells": int(total_cells),
        "viewer": {
            "mode": "sidecar-package",
            "gene_storage": "sidecar",
            "gene_manifest_path": gene_manifest_path,
            "gene_shard_dir": gene_shard_dir,
        },
        "files": files,
    }


def _write_karospace_package(
    *,
    package_path: Path,
    source_root: Path,
    entry_html: str,
    gene_manifest_path: str,
    gene_shard_dir: str,
    title: str,
    n_sections: int,
    total_cells: int,
) -> None:
    if not (source_root / entry_html).exists():
        raise FileNotFoundError(f"package entry HTML missing: {entry_html}")
    if not (source_root / gene_manifest_path).exists():
        raise FileNotFoundError(f"package gene manifest missing: {gene_manifest_path}")
    if not (source_root / gene_shard_dir).exists():
        raise FileNotFoundError(f"package gene shard directory missing: {gene_shard_dir}")

    package_path.parent.mkdir(parents=True, exist_ok=True)
    manifest = _build_karospace_package_manifest(
        source_root=source_root,
        entry_html=entry_html,
        gene_manifest_path=gene_manifest_path,
        gene_shard_dir=gene_shard_dir,
        title=title,
        n_sections=n_sections,
        total_cells=total_cells,
    )

    def _package_sort_key(path: Path) -> tuple[int, str]:
        rel_path = path.relative_to(source_root).as_posix()
        if rel_path == entry_html:
            return (0, rel_path)
        if rel_path == gene_manifest_path:
            return (1, rel_path)
        if rel_path.startswith(f"{gene_shard_dir.rstrip('/')}/"):
            return (3, rel_path)
        return (2, rel_path)

    with zipfile.ZipFile(package_path, mode="w", compression=zipfile.ZIP_DEFLATED) as zf:
        zf.writestr(
            KAROSPACE_PACKAGE_MANIFEST,
            json.dumps(manifest, separators=(",", ":")),
            compress_type=zipfile.ZIP_DEFLATED,
        )
        for file_path in sorted((p for p in source_root.rglob("*") if p.is_file()), key=_package_sort_key):
            rel_path = file_path.relative_to(source_root).as_posix()
            compress_type = zipfile.ZIP_STORED if file_path.suffix.lower() == ".bin" else zipfile.ZIP_DEFLATED
            zf.write(file_path, arcname=rel_path, compress_type=compress_type)


def _find_karospace_package_loader_template() -> Optional[Path]:
    candidates = [
        Path(__file__).resolve().with_name("package_loader.html"),
        Path(__file__).resolve().parent.parent / KAROSPACE_PACKAGE_LOADER_FILENAME,
    ]
    for candidate in candidates:
        if candidate.exists():
            return candidate
    return None


def _write_karospace_package_loader(
    *,
    loader_path: Path,
) -> Optional[Path]:
    template_path = _find_karospace_package_loader_template()
    if template_path is None:
        return None
    loader_path.parent.mkdir(parents=True, exist_ok=True)
    shutil.copyfile(template_path, loader_path)
    return loader_path


def _validate_gene_sidecar_manifest_payload(payload: dict, path: Union[str, Path]) -> None:
    supported_formats = {
        "karospace-gene-sidecar-manifest-v2",
        "karospace-gene-sidecar-manifest-v3",
        "karospace-gene-sidecar-manifest-v4",
    }
    manifest_format = payload.get("format") if isinstance(payload, dict) else None
    if manifest_format not in supported_formats:
        raise ValueError(
            f"unsupported gene sidecar manifest format in {path}: "
            f"{manifest_format!r}; expected one of {sorted(supported_formats)}"
        )


def _extract_embedded_viewer_data(html_text: str) -> dict:
    match = re.search(
        r'<script id="karospace-data" type="application/json">(.*?)</script>',
        html_text,
        re.DOTALL,
    )
    if not match:
        raise ValueError("embedded karospace-data script not found in HTML")
    data = json.loads(match.group(1).replace("<\\/", "</"))
    section_pattern = re.compile(
        r'<script type="application/json" '
        r'data-karospace-section-index="(\d+)" '
        r'data-karospace-section-key="([^"]*)"'
        r'(?: data-karospace-section-child="([^"]*)")?'
        r'>(.*?)</script>',
        re.DOTALL,
    )
    section_matches = list(section_pattern.finditer(html_text))
    if not section_matches:
        return data

    sections = data.get("sections")
    if not isinstance(sections, list):
        raise ValueError("fragmented viewer data has no sections list")
    for section_match in section_matches:
        section_index = int(section_match.group(1))
        if section_index < 0 or section_index >= len(sections):
            raise ValueError("fragmented viewer data contains an invalid section index")
        key = _html.unescape(section_match.group(2))
        child_key = section_match.group(3)
        value = json.loads(section_match.group(4).replace("<\\/", "</"))
        if not isinstance(sections[section_index], dict):
            sections[section_index] = {}
        section = sections[section_index]
        if child_key is None:
            section[key] = value
        else:
            child_key = _html.unescape(child_key)
            if not isinstance(section.get(key), dict):
                section[key] = {}
            section[key][child_key] = value
    return data


def _extract_html_title(html_text: str) -> str:
    match = re.search(r"<title>(.*?)</title>", html_text, re.DOTALL | re.IGNORECASE)
    if not match:
        return "KaroSpace"
    return str(match.group(1)).strip() or "KaroSpace"


def package_sidecar_viewer(
    html_path: Union[str, Path],
    *,
    output_path: Optional[Union[str, Path]] = None,
    gene_manifest_path: Optional[Union[str, Path]] = None,
    gene_shard_dir: Optional[Union[str, Path]] = None,
    loader_output_path: Optional[Union[str, Path]] = None,
) -> str:
    """
    Package an existing sidecar viewer bundle into a `.karospace` archive.

    Parameters
    ----------
    html_path : str or Path
        Path to an existing KaroSpace HTML viewer generated with `gene_storage="sidecar"`.
    output_path : str or Path, optional
        Output `.karospace` path. Defaults to `<html stem>.karospace`.
    gene_manifest_path : str or Path, optional
        Actual filesystem path to the sidecar gene manifest JSON if it differs from the
        path referenced in the HTML.
    gene_shard_dir : str or Path, optional
        Actual filesystem path to the sidecar shard directory if it differs from the
        manifest stem directory.
    loader_output_path : str or Path, optional
        Optional output path for the companion `.loader.html` file. Defaults to
        `<output stem>.loader.html`.

    Returns
    -------
    str
        Absolute path to the written `.karospace` package.
    """
    source_html_path = Path(html_path).expanduser().resolve()
    if not source_html_path.exists():
        raise FileNotFoundError(f"sidecar HTML not found: {source_html_path}")

    print(f"  - reading existing viewer HTML: {source_html_path}")
    html_text = source_html_path.read_text(encoding="utf-8")
    data = _extract_embedded_viewer_data(html_text)
    package_title = _extract_html_title(html_text)

    gene_aux_url = str(data.get("gene_aux_url") or "").strip()
    if not gene_aux_url:
        raise ValueError("HTML viewer does not reference a sidecar gene manifest")

    html_parent = source_html_path.parent
    package_gene_manifest_rel = Path(gene_aux_url).as_posix()
    actual_gene_manifest_path = (
        Path(gene_manifest_path).expanduser().resolve()
        if gene_manifest_path is not None
        else (html_parent / package_gene_manifest_rel).resolve()
    )
    if not actual_gene_manifest_path.exists():
        raise FileNotFoundError(f"sidecar gene manifest not found: {actual_gene_manifest_path}")
    actual_gene_manifest = json.loads(actual_gene_manifest_path.read_text(encoding="utf-8"))
    _validate_gene_sidecar_manifest_payload(actual_gene_manifest, actual_gene_manifest_path)

    package_gene_shard_rel = Path(package_gene_manifest_rel).with_suffix("").as_posix()
    actual_gene_shard_dir = (
        Path(gene_shard_dir).expanduser().resolve()
        if gene_shard_dir is not None
        else (html_parent / package_gene_shard_rel).resolve()
    )
    if not actual_gene_shard_dir.exists():
        raise FileNotFoundError(f"sidecar shard directory not found: {actual_gene_shard_dir}")

    resolved_output_path = (
        Path(output_path).expanduser().resolve()
        if output_path is not None
        else source_html_path.with_suffix(".karospace")
    )
    if resolved_output_path.suffix.lower() != ".karospace":
        raise ValueError("output_path must end with .karospace")

    resolved_loader_output_path = (
        Path(loader_output_path).expanduser().resolve()
        if loader_output_path is not None
        else resolved_output_path.with_suffix(".loader.html")
    )

    n_sections = int(data.get("n_sections") or 0)
    total_cells = int(data.get("total_cells") or 0)

    print(f"  - resolved gene manifest: {actual_gene_manifest_path}")
    print(f"  - resolved shard directory: {actual_gene_shard_dir}")
    print(f"  - package title: {package_title}")
    print(f"  - package target: {resolved_output_path}")
    print(
        f"  - packaging {n_sections} sections and {total_cells:,} cells "
        f"from existing sidecar assets"
    )

    with tempfile.TemporaryDirectory(prefix="karospace-package-") as tmpdir:
        source_root = Path(tmpdir)
        print("  - staging package assets...")
        entry_html = "index.html"
        staged_entry_html = source_root / entry_html
        staged_entry_html.write_text(html_text, encoding="utf-8")

        staged_gene_manifest = source_root / package_gene_manifest_rel
        staged_gene_manifest.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(actual_gene_manifest_path, staged_gene_manifest)

        staged_gene_shard_dir = source_root / package_gene_shard_rel
        staged_gene_shard_dir.parent.mkdir(parents=True, exist_ok=True)
        shutil.copytree(actual_gene_shard_dir, staged_gene_shard_dir, dirs_exist_ok=True)

        print("  - writing .karospace archive...")
        _write_karospace_package(
            package_path=resolved_output_path,
            source_root=source_root,
            entry_html=entry_html,
            gene_manifest_path=package_gene_manifest_rel,
            gene_shard_dir=package_gene_shard_rel,
            title=package_title,
            n_sections=n_sections,
            total_cells=total_cells,
        )

    print("  - writing local package loader...")
    written_loader_path = _write_karospace_package_loader(
        loader_path=resolved_loader_output_path,
    )

    print(f"Exported KaroSpace package to: {resolved_output_path}")
    print(f"  - entry HTML: index.html (from {source_html_path.name})")
    print(f"  - packaged gene manifest: {package_gene_manifest_rel}")
    print(f"  - packaged shard directory: {package_gene_shard_rel}")
    if written_loader_path is not None:
        print(f"  - local package loader: {written_loader_path}")
    else:
        print(f"  - local package loader: unavailable (template not found)")
    print(f"  - {n_sections} sections")
    print(f"  - {total_cells:,} cells")

    return str(resolved_output_path)


def _select_top_variable_genes(adata, n: int) -> List[str]:
    """Return up to n gene names ranked by expression variance across cells."""
    X = adata.X
    if hasattr(X, "toarray"):
        # For sparse matrices compute variance without densifying the whole thing.
        # Var(X) = E[X^2] - E[X]^2
        mean_sq = np.asarray(X.power(2).mean(axis=0)).ravel()
        sq_mean = np.asarray(X.mean(axis=0)).ravel() ** 2
        variances = mean_sq - sq_mean
    else:
        variances = np.var(np.asarray(X, dtype=float), axis=0)
    top_idx = np.argsort(variances)[::-1][:n]
    return [adata.var_names[i] for i in top_idx]


def _compute_morans_i(adata, genes: List[str], n_genes: int = 200) -> list:
    """Compute Moran's I spatial autocorrelation for the top variable genes.

    Returns a list of {gene, I} dicts sorted descending by I value, or [] if
    no spatial weight matrix is found in adata.obsp.

    W is kept sparse throughout. All genes are processed in a single sparse
    matmul (W @ Z), so cost is O(G * nnz) rather than O(G * N^2).
    """
    import scipy.sparse as sp

    # Find spatial weight matrix — keep sparse
    W = None
    for key in ("spatial_connectivities", "connectivities", "neighbors", "neighbor_graph"):
        if key in adata.obsp:
            W = adata.obsp[key]
            break
    if W is None:
        return []

    if not sp.issparse(W):
        W = sp.csr_matrix(W)
    else:
        W = W.tocsr().astype(float)

    N = W.shape[0]

    # Row-normalize in place using sparse diagonal scaling
    row_sums = np.asarray(W.sum(axis=1)).ravel()
    row_sums[row_sums == 0] = 1.0
    W = sp.diags(1.0 / row_sums) @ W
    S0 = float(W.sum())
    if S0 == 0:
        return []

    # Select top variable genes and densify only those (N × G, manageable)
    selected = _select_top_variable_genes(adata, n_genes)
    selected = [g for g in selected if g in set(genes)]
    if not selected:
        return []

    X = adata[:, selected].X
    if hasattr(X, "toarray"):
        X = X.toarray()
    X = np.asarray(X, dtype=float)          # (N, G)

    # Center each gene
    Z = X - X.mean(axis=0)                  # (N, G)

    # One sparse matmul for all genes: W @ Z  →  (N, G)
    WZ = W.dot(Z)                            # sparse × dense = dense (N, G)

    num = N * (Z * WZ).sum(axis=0)          # (G,)
    denom = S0 * (Z * Z).sum(axis=0)        # (G,)

    valid = denom > 0
    I_vals = np.where(valid, num / np.where(valid, denom, 1.0), 0.0)
    I_vals = np.clip(I_vals, -1.0, 1.0)

    results = [
        {"gene": gene, "I": round(float(I_vals[j]), 4)}
        for j, gene in enumerate(selected)
        if valid[j]
    ]
    results.sort(key=lambda d: d["I"], reverse=True)
    return results


def _compute_gene_correlations_from_category_means(
    cluster_gene_means: Optional[dict],
    genes: List[str],
    top_n: int = 10,
) -> dict:
    """Compute gene correlations across pseudobulk/category mean profiles."""
    if not genes or int(top_n) < 1:
        return {gene: [] for gene in genes} if genes else {}
    if not cluster_gene_means or not isinstance(cluster_gene_means, dict):
        return {gene: [] for gene in genes}
    mean_genes = [str(g) for g in (cluster_gene_means.get("genes") or [])]
    if len(mean_genes) < 2:
        return {gene: [] for gene in genes}
    gene_positions = {gene: idx for idx, gene in enumerate(mean_genes)}
    selected = [str(g) for g in genes if str(g) in gene_positions]
    if len(selected) < 2:
        return {gene: [] for gene in genes}

    profiles: List[List[float]] = []
    for col_data in (cluster_gene_means.get("columns") or {}).values():
        if not isinstance(col_data, dict):
            continue
        means = col_data.get("means") or {}
        for values in means.values():
            if isinstance(values, list) and len(values) == len(mean_genes):
                profiles.append([float(values[gene_positions[g]] or 0.0) for g in selected])
    if len(profiles) < 2:
        return {gene: [] for gene in genes}

    X = np.asarray(profiles, dtype=float)
    X[~np.isfinite(X)] = 0
    corr = np.corrcoef(X.T)
    result = {gene: [] for gene in genes}
    for i, gene in enumerate(selected):
        scores = corr[i].copy()
        scores[i] = -2.0
        top_idx = np.argsort(scores)[::-1][: int(top_n)]
        result[gene] = [
            {"gene": selected[j], "r": round(float(corr[i, j]), 3)}
            for j in top_idx
            if j != i and np.isfinite(corr[i, j]) and corr[i, j] > 0
        ]
    return result


def _cluster_gene_means_from_pseudobulk_de(
    pseudobulk_de: Optional[dict],
    genes: List[str],
    max_genes: int,
) -> Optional[dict]:
    """Build viewer category mean payload from pseudobulk DE aggregate summaries."""
    if not isinstance(pseudobulk_de, dict) or int(max_genes) <= 0:
        return None
    requested = [str(g) for g in genes if str(g)]
    if not requested:
        return None
    selected = requested[: int(max_genes)]
    columns = {}
    gene_order: List[str] = []
    for color_col, by_source in pseudobulk_de.items():
        if not isinstance(by_source, dict):
            continue
        summary = by_source.get("_summary") or {}
        cmeans = summary.get("category_gene_means") or {}
        src_genes = [str(g) for g in (cmeans.get("genes") or [])]
        if not src_genes:
            continue
        src_pos = {gene: idx for idx, gene in enumerate(src_genes)}
        keep = [gene for gene in selected if gene in src_pos]
        if not keep:
            continue
        if not gene_order:
            gene_order = keep
        else:
            keep = [gene for gene in gene_order if gene in src_pos]
        idx = [src_pos[gene] for gene in keep]
        means = {}
        for category, values in (cmeans.get("means") or {}).items():
            if isinstance(values, list) and len(values) == len(src_genes):
                means[str(category)] = [values[i] for i in idx]
        background_values = cmeans.get("background") or []
        background = (
            [background_values[i] for i in idx]
            if isinstance(background_values, list) and len(background_values) == len(src_genes)
            else [0.0 for _ in idx]
        )
        if means:
            columns[str(color_col)] = {
                "categories": [str(c) for c in (cmeans.get("categories") or means.keys())],
                "means": means,
                "background": background,
                "n_cells": cmeans.get("n_cells") or {},
                "source": "pseudobulk_de",
            }
    if not columns or not gene_order:
        return None
    return {"genes": gene_order, "columns": columns, "source": "pseudobulk_de"}


def _estimate_auto_spot_size(dataset: SpatialDataset, min_panel_size: int) -> float:
    """Estimate a reasonable default spot radius from section density."""
    panel_px = max(48.0, float(min_panel_size) - 16.0)  # Account for canvas padding.
    spacing_px_samples: List[float] = []

    for section in dataset.sections:
        coords = np.asarray(section.coordinates)
        if coords.ndim != 2 or coords.shape[0] < 2 or coords.shape[1] < 2:
            continue

        x = coords[:, 0]
        y = coords[:, 1]
        valid = np.isfinite(x) & np.isfinite(y)
        n = int(valid.sum())
        if n < 2:
            continue

        x = x[valid]
        y = y[valid]
        dx = float(np.max(x) - np.min(x))
        dy = float(np.max(y) - np.min(y))
        extent = max(dx, dy, 1e-12)

        # Use observed bbox area, but guard against near-line geometries.
        area = max(dx * dy, extent * extent * 0.05, 1e-12)
        spacing_data = float(np.sqrt(area / n))
        spacing_px = spacing_data * (panel_px / extent)
        if np.isfinite(spacing_px) and spacing_px > 0:
            spacing_px_samples.append(spacing_px)

    if not spacing_px_samples:
        return 10.0

    # Target a radius that keeps neighboring cells separable without looking sparse.
    est = 1.9 * float(np.median(spacing_px_samples))
    return float(np.clip(est, 1.75, 20.0))


def _resolve_spot_size(
    dataset: SpatialDataset,
    spot_size: Union[float, str, None],
    min_panel_size: int,
) -> Tuple[float, bool]:
    """
    Resolve spot size input to a numeric value.

    Returns
    -------
    Tuple[float, bool]
        (resolved_size, used_auto_mode)
    """
    if spot_size is None:
        return _estimate_auto_spot_size(dataset, min_panel_size), True

    if isinstance(spot_size, str):
        token = spot_size.strip().lower()
        if token in {"auto", "adaptive", "density"}:
            return _estimate_auto_spot_size(dataset, min_panel_size), True
        try:
            value = float(token)
        except ValueError as exc:
            raise ValueError("spot_size must be a positive number or 'auto'.") from exc
    else:
        value = float(spot_size)

    if not np.isfinite(value) or value <= 0:
        raise ValueError("spot_size must be a positive finite number or 'auto'.")
    return float(value), False


def _normalize_section_rotation(value: Union[int, float]) -> float:
    angle = float(value)
    if not np.isfinite(angle):
        raise ValueError("section rotation angles must be finite numbers")
    normalized = angle % 360.0
    if np.isclose(normalized, 360.0):
        normalized = 0.0
    return float(normalized)


def _json_sanitize_nonfinite(value):
    """Recursively replace NaN/Inf values with None for strict JSON output."""
    if isinstance(value, float):
        return value if np.isfinite(value) else None
    if isinstance(value, dict):
        return {k: _json_sanitize_nonfinite(v) for k, v in value.items()}
    if isinstance(value, list):
        return [_json_sanitize_nonfinite(v) for v in value]
    if isinstance(value, tuple):
        return [_json_sanitize_nonfinite(v) for v in value]
    return value


def _escape_html_attr(value: object) -> str:
    """Escape a short string for use inside an HTML attribute."""
    text = str(value)
    return (
        text.replace("&", "&amp;")
        .replace('"', "&quot;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def _json_for_html_script(value: object) -> str:
    """Serialize strict JSON that cannot terminate its enclosing script tag."""
    return json.dumps(value, separators=(",", ":"), allow_nan=False).replace("</", "<\\/")


def _serialize_embedded_viewer_data(data: Mapping[str, object]) -> Tuple[str, str]:
    """Return the primary viewer payload and optional, small section fragments.

    Some browsers cannot reliably parse a single JSON script node once it exceeds
    a few hundred megabytes. Sections dominate large exports, so keep the normal
    compact single-script format for ordinary viewers and split only large ones
    into one payload per section field.
    """
    sanitized_data = _json_sanitize_nonfinite(data)
    data_json = _json_for_html_script(sanitized_data)
    if len(data_json) <= EMBEDDED_VIEWER_DATA_SINGLE_SCRIPT_MAX_CHARS:
        return data_json, ""

    sections = sanitized_data.get("sections") if isinstance(sanitized_data, dict) else None
    if not isinstance(sections, list) or not sections:
        return data_json, ""

    # The main payload retains the section order but leaves their data to the
    # fragment scripts below. This keeps the initial JSON parse small as well.
    primary_data = dict(sanitized_data)
    primary_data["sections"] = [None] * len(sections)
    primary_json = _json_for_html_script(primary_data)
    if len(primary_json) > EMBEDDED_VIEWER_DATA_SINGLE_SCRIPT_MAX_CHARS:
        return data_json, ""

    fragments: List[str] = []

    def append_fragment(
        section_index: int,
        key: object,
        value: object,
        *,
        child_key: Optional[object] = None,
    ) -> None:
        payload = _json_for_html_script(value)
        attrs = (
            'type="application/json" '
            f'data-karospace-section-index="{section_index}" '
            f'data-karospace-section-key="{_escape_html_attr(key)}"'
        )
        if child_key is not None:
            attrs += f' data-karospace-section-child="{_escape_html_attr(child_key)}"'
        fragments.append(f"<script {attrs}>{payload}</script>")

    for section_index, section in enumerate(sections):
        if not isinstance(section, dict):
            raise ValueError(
                "large viewer export requires each section payload to be a mapping"
            )
        for key, value in section.items():
            payload = _json_for_html_script(value)
            if len(payload) <= EMBEDDED_VIEWER_DATA_SINGLE_SCRIPT_MAX_CHARS:
                append_fragment(section_index, key, value)
                continue
            if isinstance(value, dict):
                # Dense dictionaries (for example encoded annotations or genes)
                # can themselves be large; split their entries as well.
                append_fragment(section_index, key, {})
                for child_key, child_value in value.items():
                    child_payload = _json_for_html_script(child_value)
                    if len(child_payload) > EMBEDDED_VIEWER_DATA_SINGLE_SCRIPT_MAX_CHARS:
                        raise ValueError(
                            "large viewer export contains a section field that exceeds "
                            f"{EMBEDDED_VIEWER_DATA_SINGLE_SCRIPT_MAX_CHARS // (1024 * 1024)} MB "
                            f"even after splitting: section {section_index}, {key!r}, {child_key!r}. "
                            "Use downsampling to reduce the exported cells per section."
                        )
                    append_fragment(section_index, key, child_value, child_key=child_key)
                continue
            raise ValueError(
                "large viewer export contains a section field that exceeds "
                f"{EMBEDDED_VIEWER_DATA_SINGLE_SCRIPT_MAX_CHARS // (1024 * 1024)} MB: "
                f"section {section_index}, {key!r}. Use downsampling to reduce the "
                "exported cells per section."
            )

    return primary_json, "\n    ".join(fragments)


def _resolve_section_rotations(
    dataset: SpatialDataset,
    section_rotations: Optional[Mapping[str, Union[int, float]]],
) -> Dict[str, float]:
    if section_rotations is None:
        return {}
    if not isinstance(section_rotations, Mapping):
        raise TypeError("section_rotations must be a mapping of section_id -> angle")

    valid_ids = {section.section_id for section in dataset.sections}
    resolved: Dict[str, float] = {}
    unknown_ids = sorted(str(section_id) for section_id in section_rotations if str(section_id) not in valid_ids)
    if unknown_ids:
        raise ValueError(
            "section_rotations contains unknown section_id values: " + ", ".join(unknown_ids)
        )

    for raw_section_id, raw_angle in section_rotations.items():
        section_id = str(raw_section_id)
        try:
            resolved[section_id] = _normalize_section_rotation(raw_angle)
        except (TypeError, ValueError) as exc:
            raise ValueError(
                f"section_rotations[{section_id!r}] must be a finite numeric angle"
            ) from exc

    return resolved


